// Gate confirmation image (JPEG, base64). Shown after a correct PIN at /gate/confirm.jpg.
const CONFIRM_B64 = "";

export function confirmBytes() {
  const bin = atob(CONFIRM_B64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
